package panel

func subscriptionTemplateAPISpec(paths, schemas Data) {
	schemas["SubscriptionInfo"] = Data{"type": "object", "description": "Current subscription metadata only; no configuration or connection credentials", "properties": Data{"enabled": Data{"type": "boolean"}, "isOnline": Data{"type": []any{"boolean", "null"}}, "usedByte": Data{"type": "integer", "description": "Charged quota bytes"}, "downloadByte": Data{"type": "integer", "description": "Actual download bytes"}, "uploadByte": Data{"type": "integer", "description": "Actual upload bytes"}, "totalByte": Data{"type": "integer"}, "expire": Data{"type": "integer", "description": "Unix milliseconds, zero for unlimited"}, "lastOnline": Data{"type": "integer", "description": "Last traffic Unix milliseconds, zero if unknown"}}}
	paths["/sub/{token}"] = Data{"parameters": []any{Data{"name": "token", "in": "path", "required": true, "schema": Data{"type": "string", "minLength": 16, "maxLength": 96}}, Data{"name": "format", "in": "query", "schema": Data{"enum": []any{"portal", "base64", "raw", "clash", "singbox", "xray", "json", "info", "qr", "stats", "wireguard"}}}, Data{"name": "data", "in": "query", "description": "QR only: exact own subscription/feed or exported URI; not an arbitrary encoder", "schema": Data{"type": "string", "maxLength": 8192}}}, "get": Data{"summary": "Token-scoped subscription; existing activity/device policy applies", "security": []any{}, "responses": Data{"200": Data{"description": "Requested representation", "content": Data{"application/json": Data{"schema": Data{"description": "format=info uses SubscriptionInfo; other JSON formats retain their existing contracts", "anyOf": []any{Data{"$ref": "#/components/schemas/SubscriptionInfo"}, Data{"type": "object"}, Data{"type": "array"}}}}, "image/png": Data{"schema": Data{"type": "string", "format": "binary"}}, "text/html": Data{"schema": Data{"type": "string"}}}}, "403": Data{"description": "Inactive subscription or denied device"}, "400": Data{"description": "Unsupported format or foreign/oversized QR data"}}}}
}
